const RTCRM=(()=>{
 const colors=['#84909e','#d32f2f','#ed8500','#d1a600','#268547','#5376cd'];
 let profiles={},authState='anonymous',records={},excluded=[],canEdit=false,ready=false,error='';
 const defaults=()=>({level:0,note:'',follow:0,action:'',status:'new',slots:'[]'});
 function get(id){return {...defaults(),...records[id]}}
 function key(a){return String(a||'').normalize('NFKC').toLowerCase().replace(/[‐‑‒–—]/g,'-').replace(/\b(road|street|avenue|boulevard|crescent|drive|parade|court|victoria)\b/g,x=>({road:'rd',street:'st',avenue:'ave',boulevard:'blvd',crescent:'cres',drive:'dr',parade:'pde',court:'ct',victoria:'vic'})[x]).replace(/\b(australia|vic|\d{4})\b/g,'').replace(/[^a-z0-9]/g,'')}
 function visible(e){return !excluded.some(x=>x.id===e.id||x.key===key(e.originalAddress||e.address))}
 async function load(){try{const r=await fetch('/api/workspace',{cache:'no-store'}),v=await r.json();if(!r.ok)throw Error(v.error);records=Object.fromEntries(v.records.map(x=>[x.id,x]));excluded=v.excluded;profiles=Object.fromEntries((v.profiles||[]).map(x=>[x.id,JSON.parse(x.data)]));authState=v.authState;canEdit=v.canEdit;ready=true;error=''}catch(e){error=e.message;ready=false}}
 async function save(id,values){const r=await fetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({operation:'save',id,...values})}),v=await r.json();if(!r.ok)throw Error(v.error);records[id]={...get(id),id,...values,status:v.status,follow:v.status==='follow'?1:0,updated:v.updated};return v}
 async function remove(e,reason){const r=await fetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({operation:'exclude',id:e.id,reason})}),v=await r.json();if(!r.ok)throw Error(v.error);excluded.push({key:v.key,id:e.id,address:e.address})}
 async function changeStatus(id,status,confirmedPaid=false){const r=await fetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({operation:'status',id,status,confirmedPaid})}),v=await r.json();if(!r.ok)throw Error(v.error);records[id]={...get(id),status:v.status,follow:v.status==='follow'?1:0,updated:v.updated};return v}
 function slots(id){try{return JSON.parse(get(id).slots||'[]')}catch{return []}}
 async function saveSlots(id,slots){const r=await fetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({operation:'slots',id,slots})}),v=await r.json();if(!r.ok)throw Error(v.error);records[id]={...get(id),slots:JSON.stringify(v.slots),updated:v.updated};return v}
 function routes(e){const c=e.channels||{},link=n=>c[n]?.[0]?.url||'',email=e.emails?.[0]||e.legacy_contact?.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i)?.[0],phone=e.phones?.[0]||e.legacy_contact?.match(/(?:0[23478]\s*)?\d{4}\s*\d{4}|04\d{2}\s*\d{3}\s*\d{3}/)?.[0];return [{name:'Email',icon:'✉',url:email?'mailto:'+email:''},{name:'Phone',icon:'☎',url:phone?'tel:'+phone.replace(/[^+0-9]/g,''):''},{name:'WhatsApp',icon:'WA',url:link('WhatsApp')||e.whatsapp||''},{name:'Facebook',icon:'f',url:link('Facebook')},{name:'Website',icon:'◎',url:link('Organisation websites')},{name:'Instagram',icon:'IG',url:link('Instagram')},{name:'TikTok',icon:'♪',url:link('TikTok')}];}
 function completeness(e){return routes(e).filter(x=>x.url).length}
 function star(id){const n=get(id).level;return `<span class="manual-star" style="color:${colors[n]}" title="${n?'Manual Level '+n:'Not rated'}" aria-label="${n?'Manual Level '+n:'Not rated'}">★ <small>${n?'L'+n:'—'}</small></span>`}
 async function saveProfile(id,profile){const r=await fetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({operation:'profile',id,profile})}),v=await r.json();if(!r.ok)throw Error(v.error);profiles[id]=profile;}
 function apply(rows){for(const l of rows){const p=profiles[l.id];if(!p)continue;if(!l.originalAddress)l.originalAddress=l.address;l.name=p.name;l.address=p.address;if(p.address!==l.originalAddress){l.geo_evidence='地址已手工修改；地图坐标仍来自原始档案 / Address edited; map coordinates refer to the original record.';}l.phones=p.phone?[p.phone]:[];l.emails=p.email?[p.email]:[];l.channels['Organisation websites']=p.website?[{url:p.website,evidence_kind:'owner_edited'}]:[];l.profile_summary[0].body={zh:p.summaryZh,en:p.summaryEn};l.profile_summary[1].body={zh:p.address,en:p.address};l.profile_summary[2].body={zh:[p.email,p.phone].filter(Boolean).join(' · '),en:[p.email,p.phone].filter(Boolean).join(' · ')};}}
 return {apply,saveProfile,profile:id=>profiles[id],get authState(){return authState},get exclusions(){return excluded},get,load,save,changeStatus,slots,saveSlots,remove,visible,key,routes,completeness,star,colors,get canEdit(){return canEdit},get ready(){return ready},get error(){return error},get excludedCount(){return excluded.length}};
})();
